import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_tanh_forward(torch::Tensor x);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void tanh_kernel_vec4(
    const float* __restrict__ X,
    float* __restrict__ Y,
    int64_t N)
{
  constexpr int VecSize = 4;
  int64_t vecN = N / VecSize;

  // View memory as arrays of float4 using CuTe tensors.
  auto mX = make_tensor(
      make_gmem_ptr(reinterpret_cast<const float4*>(X)),
      make_shape(vecN),
      make_stride(Int<1>{}));
  auto mY = make_tensor(
      make_gmem_ptr(reinterpret_cast<float4*>(Y)),
      make_shape(vecN),
      make_stride(Int<1>{}));

  int64_t idx    = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  int64_t stride = (int64_t)gridDim.x * blockDim.x;

  for (int64_t i = idx; i < vecN; i += stride) {
    float4 v = mX(i);
    float4 r;
    r.x = tanhf(v.x);
    r.y = tanhf(v.y);
    r.z = tanhf(v.z);
    r.w = tanhf(v.w);
    mY(i) = r;
  }

  // Tail elements that don't fit into a float4 group.
  int64_t tail_start = vecN * VecSize;
  for (int64_t i = tail_start + idx; i < N; i += stride) {
    Y[i] = tanhf(X[i]);
  }
}

torch::Tensor cute_tanh_forward(torch::Tensor x) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

  auto x_c = x.contiguous();
  auto y   = torch::empty_like(x_c);

  int64_t N = x_c.numel();

  const float* x_ptr = x_c.data_ptr<float>();
  float* y_ptr = y.data_ptr<float>();

  constexpr int VecSize = 4;
  int64_t vecN = N / VecSize;
  int64_t work_units = vecN > 0 ? vecN : N; // number of "parallel units" to size the grid on

  int threads = 256;
  int64_t blocks64 = (work_units + threads - 1) / threads;
  if (blocks64 < 1) blocks64 = 1;
  // Cap grid size to a reasonable number; kernel loops with stride to cover all elements.
  int64_t max_blocks = 65535;
  int blocks = (int)(blocks64 > max_blocks ? max_blocks : blocks64);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  tanh_kernel_vec4<<<blocks, threads, 0, stream>>>(x_ptr, y_ptr, N);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "tanh_kernel_vec4 launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

cute_tanh_ext = load_inline(
    name="cute_tanh_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["cute_tanh_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs a Tanh activation using a custom CuTe/CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_tanh_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_tanh_forward(x)

