import torch
import torch.nn as nn

from cutegen.ptx_runtime import PtxModule, u64, i64

PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64

.visible .entry tanh_kernel(
    .param .u64 tanh_kernel_param_0,   // const float* X
    .param .u64 tanh_kernel_param_1,   // float* Y
    .param .u64 tanh_kernel_param_2    // int64_t N (element count)
)
{
    .reg .pred %p<4>;
    .reg .f32  %f<12>;
    .reg .b32  %r<14>;
    .reg .b64  %rd<20>;

    ld.param.u64    %rd1, [tanh_kernel_param_0];
    ld.param.u64    %rd2, [tanh_kernel_param_1];
    ld.param.u64    %rd3, [tanh_kernel_param_2];

    cvta.to.global.u64 %rd4, %rd1;
    cvta.to.global.u64 %rd5, %rd2;

    // idx = blockIdx.x * blockDim.x + threadIdx.x
    mov.u32         %r1, %ctaid.x;
    mov.u32         %r2, %ntid.x;
    mov.u32         %r3, %tid.x;
    mad.lo.s32      %r4, %r1, %r2, %r3;
    cvt.s64.s32     %rd6, %r4;

    // stride = gridDim.x * blockDim.x
    mov.u32         %r5, %nctaid.x;
    mul.lo.s32      %r6, %r5, %r2;
    cvt.s64.s32     %rd7, %r6;

$L_loop_top:
    setp.ge.s64     %p1, %rd6, %rd3;
    @%p1 bra        $L_done;

    // byte offset = idx * 4
    shl.b64         %rd8, %rd6, 2;
    add.s64         %rd9,  %rd4, %rd8;   // &X[idx]
    add.s64         %rd10, %rd5, %rd8;   // &Y[idx]

    ld.global.f32   %f1, [%rd9];

    // tanh(x) = sign(x) * (1 - 2 / (exp(2*|x|) + 1))
    abs.f32         %f2, %f1;
    mul.f32         %f3, %f2, 0f4038AA3B;      // |x| * 2*log2(e)
    ex2.approx.ftz.f32 %f4, %f3;               // exp(2*|x|)
    add.f32         %f5, %f4, 0f3F800000;      // + 1
    rcp.approx.ftz.f32 %f6, %f5;               // 1/(exp(2|x|)+1)
    fma.rn.f32      %f7, %f6, 0fC0000000, 0f3F800000; // 1 - 2*r

    // copy sign of original x onto result
    mov.b32         %r7, %f7;
    mov.b32         %r8, %f1;
    and.b32         %r9, %r8, -2147483648;
    or.b32          %r10, %r9, %r7;
    mov.b32         %f8, %r10;

    st.global.f32   [%rd10], %f8;

    add.s64         %rd6, %rd6, %rd7;
    bra.uni         $L_loop_top;

