class ModelNew(nn.Module):
    """
    Tanh activation implemented as a hand-authored PTX kernel launched via
    cutegen.ptx_runtime.PtxModule.
    """

    def __init__(self):
        super().__init__()
        self._module = None

    def _get_module(self) -> PtxModule:
        if self._module is None:
            self._module = PtxModule(PTX_SOURCE)
        return self._module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "x must be a CUDA tensor"
        assert x.dtype == torch.float32, "x must be float32"

        x_c = x.contiguous()
        y = torch.empty_like(x_c)

        n = x_c.numel()
        module = self._get_module()

        threads = 256
        blocks = (n + threads - 1) // threads
        blocks = max(1, min(blocks, 65535))

        stream = torch.cuda.current_stream().cuda_stream

        module.launch(
            "tanh_kernel",
            grid=(blocks, 1, 1),
            block=(threads, 1, 1),
            args=[u64(x_c.data_ptr()), u64(y.data_ptr()), i64(n)],
            stream=stream,
        )

        return y.view_as(x)


def validate_generated_code():
    module = PtxModule(PTX_SOURCE)
    fn = module.function("tanh_kernel")
    assert fn is not None, "tanh_kernel entry not found in PTX module"
    return fn
